import { describe, expect, it } from 'vitest';
import type Database from 'better-sqlite3';
import { openDatabase } from '../../src/store/db.js';
import { migrate } from '../../src/store/schema.js';

function freshDb(): Database.Database {
  return openDatabase(':memory:');
}

describe('T-003 schema migrate', () => {
  it('migrate 两次幂等且 user_version 为 1', () => {
    const db = freshDb();
    expect(db.pragma('user_version', { simple: true })).toBe(1);
    migrate(db);
    migrate(db);
    expect(db.pragma('user_version', { simple: true })).toBe(1);
    const tables = db
      .prepare(
        `SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name`,
      )
      .all() as { name: string }[];
    expect(tables.map((t) => t.name)).toEqual([
      'consent',
      'entry',
      'entry_member',
      'event',
      'ingestion_run',
      'member',
      'push_log',
      'report',
      'source_link',
    ]);
  });

  it('拒绝非法 report.status', () => {
    const db = freshDb();
    db.prepare(
      `INSERT INTO member (github_login, display_name, active, created_at) VALUES ('a', 'A', 1, '2026-01-01T00:00:00+08:00')`,
    ).run();
    expect(() =>
      db
        .prepare(
          `INSERT INTO report (member_id, report_date, status, generated_at) VALUES (1, '2026-11-25', 'invalid', '2026-11-25T18:00:00+08:00')`,
        )
        .run(),
    ).toThrow();
  });

  it('外键开启时拒绝无效 member_id', () => {
    const db = freshDb();
    expect(() =>
      db
        .prepare(
          `INSERT INTO event (member_id, source, source_id, kind, occurred_at, title, dedupe_key, is_primary, run_id, created_at)
           VALUES (999, 'github', 'x', 'commit', '2026-11-25T10:00:00+08:00', 't', 'dk1', 1, 'run', '2026-11-25T10:00:00+08:00')`,
        )
        .run(),
    ).toThrow();
  });

  it('member 可写入 email', () => {
    const db = freshDb();
    db.prepare(
      `INSERT INTO member (github_login, display_name, email, active, created_at) VALUES ('u', 'U', 'u@example.com', 1, '2026-01-01T00:00:00+08:00')`,
    ).run();
    const row = db.prepare(`SELECT email FROM member WHERE github_login = 'u'`).get() as {
      email: string;
    };
    expect(row.email).toBe('u@example.com');
  });

  it('entry_member 主键重复插入失败', () => {
    const db = freshDb();
    const now = '2026-11-25T10:00:00+08:00';
    db.prepare(
      `INSERT INTO member (github_login, display_name, active, created_at) VALUES ('m', 'M', 1, ?)`,
    ).run(now);
    db.prepare(
      `INSERT INTO report (member_id, report_date, status, generated_at) VALUES (1, '2026-11-25', 'draft', ?)`,
    ).run(now);
    db.prepare(
      `INSERT INTO entry (report_id, time_block, state, content, order_index, attribution_kind, attribution_confirmed, is_manual)
       VALUES (1, 'morning', 'done', 'c', 0, 'author', 1, 0)`,
    ).run();
    db.prepare(`INSERT INTO entry_member (entry_id, member_id, role) VALUES (1, 1, 'primary')`).run();
    expect(() =>
      db.prepare(`INSERT INTO entry_member (entry_id, member_id, role) VALUES (1, 1, 'co')`).run(),
    ).toThrow();
  });
});

import { describe, expect, it } from 'vitest';
import { FixedClock } from '../../src/clock.js';
import { ERROR_CODES, SdrError } from '../../src/errors.js';
import { openDatabase } from '../../src/store/db.js';
import {
  HistoryAccessDenied,
  SUMMARY_ROWS_SQL,
  createRepo,
  type SaveReportBundleInput,
} from '../../src/store/repo.js';
import type { Event, Member } from '../../src/types.js';

const clock = new FixedClock(new Date('2026-11-25T12:00:00+08:00'));

function member(overrides: Partial<Member> = {}): Omit<Member, 'id'> {
  return {
    githubLogin: 'dev',
    displayName: '开发者',
    active: true,
    ...overrides,
  };
}

function sampleEvent(dedupeKey: string): Event {
  return {
    memberId: 1,
    source: 'github',
    sourceId: 'abc',
    kind: 'commit',
    occurredAt: new Date('2026-11-25T09:00:00+08:00'),
    title: 'feat: x',
    dedupeKey,
    isPrimary: true,
    runId: 'run-1',
  };
}

describe('T-004 repository', () => {
  it('upsertEvent 相同 dedupe_key 二次写入仍为一行', () => {
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    repo.insertMember(member());
    const ev = sampleEvent('dedupe-a');
    repo.upsertEvent(ev);
    repo.upsertEvent({ ...ev, title: 'changed title' });
    const count = (db.prepare(`SELECT COUNT(*) AS c FROM event`).get() as { c: number }).c;
    expect(count).toBe(1);
    const row = repo.upsertEvent(ev);
    expect(row.title).toBe('feat: x');
  });

  it('saveReportBundle 冲突时整批回滚', () => {
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    repo.insertMember(member());
    const bundle: SaveReportBundleInput = {
      report: {
        memberId: 1,
        reportDate: '2026-11-25',
        status: 'draft',
        generatedAt: clock.now(),
      },
      entries: [
        {
          timeBlock: 'morning',
          state: 'done',
          content: '工作一',
          orderIndex: 0,
          attributionKind: 'author',
          attributionConfirmed: true,
          isManual: false,
          members: [{ memberId: 1, role: 'primary' }],
          links: [{ linkType: 'url', target: 'https://example.com/a' }],
        },
        {
          timeBlock: 'afternoon',
          state: 'doing',
          content: '工作二',
          orderIndex: 0,
          attributionKind: 'fallback',
          attributionConfirmed: false,
          isManual: false,
          members: [
            { memberId: 1, role: 'primary' },
            { memberId: 1, role: 'co' },
          ],
          links: [{ linkType: 'note', target: '手工说明' }],
        },
      ],
    };
    expect(() => repo.saveReportBundle(bundle)).toThrowError(
      expect.objectContaining({ code: ERROR_CODES.STORE_TRANSACTION_FAILED }),
    );
    expect((db.prepare(`SELECT COUNT(*) AS c FROM report`).get() as { c: number }).c).toBe(0);
    expect((db.prepare(`SELECT COUNT(*) AS c FROM entry`).get() as { c: number }).c).toBe(0);
    expect((db.prepare(`SELECT COUNT(*) AS c FROM entry_member`).get() as { c: number }).c).toBe(
      0,
    );
    expect((db.prepare(`SELECT COUNT(*) AS c FROM source_link`).get() as { c: number }).c).toBe(0);
  });

  it('acceptAttribution 确认待确认条目并返回条数', () => {
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    repo.insertMember(member());
    const { reportId } = repo.saveReportBundle({
      report: {
        memberId: 1,
        reportDate: '2026-11-25',
        status: 'draft',
        generatedAt: clock.now(),
      },
      entries: [
        {
          timeBlock: 'morning',
          state: 'blocked',
          content: '阻塞项',
          orderIndex: 0,
          attributionKind: 'fallback',
          attributionConfirmed: false,
          isManual: false,
          members: [{ memberId: 1, role: 'primary' }],
          links: [{ linkType: 'path', target: '/tmp/x' }],
        },
        {
          timeBlock: 'afternoon',
          state: 'done',
          content: '已完成',
          orderIndex: 0,
          attributionKind: 'author',
          attributionConfirmed: true,
          isManual: false,
          members: [{ memberId: 1, role: 'primary' }],
          links: [{ linkType: 'url', target: 'https://example.com' }],
        },
      ],
    });
    const n = repo.acceptAttribution(reportId, true);
    expect(n).toBe(1);
    const pending = (
      db.prepare(`SELECT COUNT(*) AS c FROM entry WHERE attribution_confirmed = 0`).get() as {
        c: number;
      }
    ).c;
    expect(pending).toBe(0);
  });

  it('findSummaryRows 查询 SQL 不含 content 列', () => {
    expect(SUMMARY_ROWS_SQL.toLowerCase()).not.toContain('content');
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    repo.insertMember(member({ displayName: '张三' }));
    repo.saveReportBundle({
      report: {
        memberId: 1,
        reportDate: '2026-11-26',
        status: 'confirmed',
        generatedAt: clock.now(),
      },
      entries: [
        {
          timeBlock: 'morning',
          state: 'done',
          content: '不应出现在汇总 SQL',
          orderIndex: 0,
          attributionKind: 'author',
          attributionConfirmed: true,
          isManual: false,
          members: [{ memberId: 1, role: 'primary' }],
          links: [{ linkType: 'url', target: 'https://x' }],
        },
      ],
    });
    const rows = repo.findSummaryRows('2026-11-26');
    expect(rows).toHaveLength(1);
    expect(rows[0]?.entryCount).toBe(1);
    expect(rows[0]?.byState.done).toBe(1);
  });

  it('findHistory 仅本人或直属上级可访问', () => {
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    const leadId = repo.insertMember(
      member({ githubLogin: 'lead', displayName: '组长' }),
    ).id;
    const memberId = repo.insertMember(
      member({ githubLogin: 'ic', displayName: '员工', managerId: leadId }),
    ).id;
    const outsiderId = repo.insertMember(
      member({ githubLogin: 'other', displayName: '外人' }),
    ).id;
    repo.saveReportBundle({
      report: {
        memberId,
        reportDate: '2026-11-25',
        status: 'draft',
        generatedAt: clock.now(),
      },
      entries: [],
    });
    expect(() =>
      repo.findHistory(outsiderId, memberId, '2026-11-01', '2026-11-30'),
    ).toThrow(HistoryAccessDenied);
    const self = repo.findHistory(memberId, memberId, '2026-11-01', '2026-11-30');
    expect(self).toHaveLength(1);
    const mgr = repo.findHistory(leadId, memberId, '2026-11-01', '2026-11-30');
    expect(mgr).toHaveLength(1);
  });

  it('getMember 回读 email', () => {
    const db = openDatabase(':memory:');
    const repo = createRepo(db, clock);
    const id = repo.insertMember(
      member({ email: 'dev@corp.example', githubLogin: 'e' }),
    ).id;
    expect(repo.getMember(id)?.email).toBe('dev@corp.example');
  });
});

import type Database from 'better-sqlite3';

const SCHEMA_V1 = `
CREATE TABLE member (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  github_login TEXT NOT NULL UNIQUE,
  feishu_open_id TEXT UNIQUE,
  display_name TEXT NOT NULL,
  email TEXT,
  manager_id INTEGER REFERENCES member(id),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at TEXT NOT NULL
);

CREATE TABLE event (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL REFERENCES member(id),
  source TEXT NOT NULL CHECK (source IN ('github', 'feishu', 'local', 'manual')),
  source_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('commit', 'task_done', 'file_change', 'note')),
  occurred_at TEXT NOT NULL,
  title TEXT NOT NULL,
  detail TEXT,
  dedupe_key TEXT NOT NULL UNIQUE,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  run_id TEXT NOT NULL,
  payload TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE report (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL REFERENCES member(id),
  report_date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('draft', 'confirmed', 'leave', 'blank')),
  body TEXT,
  generated_at TEXT NOT NULL,
  pushed_at TEXT,
  UNIQUE(member_id, report_date)
);

CREATE TABLE entry (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  report_id INTEGER NOT NULL REFERENCES report(id),
  time_block TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('done', 'doing', 'plan', 'blocked')),
  content TEXT NOT NULL,
  order_index INTEGER NOT NULL,
  original_date TEXT,
  source_event_id INTEGER REFERENCES event(id),
  is_manual INTEGER NOT NULL DEFAULT 0 CHECK (is_manual IN (0, 1)),
  attribution_kind TEXT NOT NULL DEFAULT 'author'
    CHECK (attribution_kind IN ('author', 'coauthor', 'task_window', 'fallback')),
  attribution_confirmed INTEGER NOT NULL DEFAULT 1 CHECK (attribution_confirmed IN (0, 1))
);

CREATE TABLE entry_member (
  entry_id INTEGER NOT NULL REFERENCES entry(id),
  member_id INTEGER NOT NULL REFERENCES member(id),
  role TEXT NOT NULL CHECK (role IN ('primary', 'co')),
  PRIMARY KEY (entry_id, member_id)
);

CREATE TABLE source_link (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  entry_id INTEGER NOT NULL REFERENCES entry(id),
  link_type TEXT NOT NULL CHECK (link_type IN ('url', 'path', 'note')),
  target TEXT NOT NULL
);

CREATE TABLE ingestion_run (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('github', 'feishu', 'local', 'manual')),
  started_at TEXT NOT NULL,
  finished_at TEXT,
  result TEXT NOT NULL CHECK (result IN ('ok', 'partial', 'failed', 'skipped')),
  error_code TEXT,
  error_msg TEXT,
  event_count INTEGER NOT NULL DEFAULT 0,
  UNIQUE(run_id, source)
);

CREATE TABLE push_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  report_date TEXT NOT NULL,
  channel TEXT NOT NULL,
  sent_at TEXT NOT NULL,
  result TEXT NOT NULL,
  retry_count INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE consent (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL REFERENCES member(id),
  agreed_at TEXT NOT NULL,
  scope TEXT NOT NULL
);
`;

export function migrate(db: Database.Database): void {
  const version = db.pragma('user_version', { simple: true }) as number;
  if (version === 0) {
    db.exec(SCHEMA_V1);
    db.pragma('user_version = 1');
    return;
  }
  if (version !== 1) {
    throw new Error(`unsupported schema version: ${version}`);
  }
}

import Database from 'better-sqlite3';
import { migrate } from './schema.js';

export function openDatabase(path: string): Database.Database {
  const db = new Database(path);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  migrate(db);
  return db;
}

