import type { Entry, EntryMember, EntryState, Event, Member, Report, ReportStatus, Source, SourceLink } from '../types.js';

export class HistoryAccessDenied extends Error {
  override readonly name = 'HistoryAccessDenied';

  constructor() {
    super('无权访问该成员历史日报');
  }
}

export const SUMMARY_ROWS_SQL = `
SELECT
  m.id AS member_id,
  m.display_name,
  r.status,
  e.state,
  COUNT(*) AS state_count
FROM member m
LEFT JOIN report r ON r.member_id = m.id AND r.report_date = ?
LEFT JOIN entry e ON e.report_id = r.id
WHERE m.active = 1
GROUP BY m.id, m.display_name, r.status, e.state
ORDER BY m.display_name
`;

export type MemberRow = {
  id: number;
  github_login: string;
  feishu_open_id: string | null;
  display_name: string;
  email: string | null;
  manager_id: number | null;
  active: number;
  created_at: string;
};

export type EventRow = {
  id: number;
  member_id: number;
  source: Source;
  source_id: string;
  kind: Event['kind'];
  occurred_at: string;
  title: string;
  detail: string | null;
  dedupe_key: string;
  is_primary: number;
  run_id: string;
  payload: string | null;
  created_at: string;
};

export interface SaveReportBundleEntry {
  readonly timeBlock: string;
  readonly state: Entry['state'];
  readonly content: string;
  readonly orderIndex: number;
  readonly originalDate?: string;
  readonly sourceEventId?: number;
  readonly isManual: boolean;
  readonly attributionKind: Entry['attributionKind'];
  readonly attributionConfirmed: boolean;
  readonly members: ReadonlyArray<Omit<EntryMember, 'entryId'>>;
  readonly links: ReadonlyArray<Omit<SourceLink, 'entryId'>>;
}

export interface SaveReportBundleInput {
  readonly report: Omit<Report, 'id'>;
  readonly entries: readonly SaveReportBundleEntry[];
}

export interface HistoryReport {
  readonly report: Report;
  readonly entries: Entry[];
}

export interface IngestionRunInput {
  readonly runId: string;
  readonly source: Source;
  readonly startedAt: Date;
  readonly finishedAt?: Date;
  readonly result: 'ok' | 'partial' | 'failed' | 'skipped';
  readonly errorCode?: string;
  readonly errorMsg?: string;
  readonly eventCount: number;
}

export interface PushLogInput {
  readonly reportDate: string;
  readonly channel: string;
  readonly sentAt: Date;
  readonly result: string;
  readonly retryCount?: number;
}

export interface ConsentInput {
  readonly memberId: number;
  readonly agreedAt: Date;
  readonly scope: string;
}

export type SummaryQueryRow = {
  member_id: number;
  display_name: string;
  status: ReportStatus | null;
  state: EntryState | null;
  state_count: number;
};

export type ReportRow = {
  id: number;
  member_id: number;
  report_date: string;
  status: ReportStatus;
  body: string | null;
  generated_at: string;
  pushed_at: string | null;
};

export type EntryRow = {
  id: number;
  report_id: number;
  time_block: string;
  state: EntryState;
  content: string;
  order_index: number;
  original_date: string | null;
  source_event_id: number | null;
  is_manual: number;
  attribution_kind: Entry['attributionKind'];
  attribution_confirmed: number;
};

import { parseInstant } from '../clock.js';
import type { Entry, EntryState, Event, Member } from '../types.js';
import type { EntryRow, EventRow, MemberRow, ReportRow } from './repo-types.js';

export function emptyByState(): Record<EntryState, number> {
  return { done: 0, doing: 0, plan: 0, blocked: 0 };
}

export function mapMemberFull(row: MemberRow): Member {
  return {
    id: row.id,
    githubLogin: row.github_login,
    displayName: row.display_name,
    active: row.active === 1,
    ...(row.feishu_open_id !== null ? { feishuOpenId: row.feishu_open_id } : {}),
    ...(row.email !== null ? { email: row.email } : {}),
    ...(row.manager_id !== null ? { managerId: row.manager_id } : {}),
  };
}

export function mapEvent(row: EventRow): Event {
  const base: Event = {
    id: row.id,
    memberId: row.member_id,
    source: row.source,
    sourceId: row.source_id,
    kind: row.kind,
    occurredAt: parseInstant(row.occurred_at),
    title: row.title,
    dedupeKey: row.dedupe_key,
    isPrimary: row.is_primary === 1,
    runId: row.run_id,
  };
  if (row.detail !== null) {
    const withDetail = { ...base, detail: row.detail };
    if (row.payload !== null) {
      return { ...withDetail, payload: JSON.parse(row.payload) as unknown };
    }
    return withDetail;
  }
  if (row.payload !== null) {
    return { ...base, payload: JSON.parse(row.payload) as unknown };
  }
  return base;
}

export function mapEntryRow(e: EntryRow): Entry {
  return {
    id: e.id,
    reportId: e.report_id,
    timeBlock: e.time_block,
    state: e.state,
    content: e.content,
    orderIndex: e.order_index,
    isManual: e.is_manual === 1,
    attributionKind: e.attribution_kind,
    attributionConfirmed: e.attribution_confirmed === 1,
    ...(e.original_date !== null ? { originalDate: e.original_date } : {}),
    ...(e.source_event_id !== null ? { sourceEventId: e.source_event_id } : {}),
  };
}

export function mapReportRow(row: ReportRow): import('../types.js').Report {
  return {
    id: row.id,
    memberId: row.member_id,
    reportDate: row.report_date,
    status: row.status,
    generatedAt: parseInstant(row.generated_at),
    ...(row.body !== null ? { body: row.body } : {}),
    ...(row.pushed_at !== null ? { pushedAt: parseInstant(row.pushed_at) } : {}),
  };
}

export function isUniqueViolation(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as { code: string }).code === 'SQLITE_CONSTRAINT_UNIQUE'
  );
}

import type Database from 'better-sqlite3';
import { toZonedIsoString } from '../clock.js';
import { ERROR_CODES, SdrError } from '../errors.js';
import type { Clock, EntryState, Event, Member, ReportStatus, SummaryRow } from '../types.js';
import {
  emptyByState,
  isUniqueViolation,
  mapEntryRow,
  mapEvent,
  mapMemberFull,
  mapReportRow,
} from './repo-map.js';
import {
  HistoryAccessDenied,
  SUMMARY_ROWS_SQL,
  type ConsentInput,
  type EventRow,
  type HistoryReport,
  type IngestionRunInput,
  type MemberRow,
  type PushLogInput,
  type SaveReportBundleInput,
  type SummaryQueryRow,
} from './repo-types.js';

export {
  HistoryAccessDenied,
  SUMMARY_ROWS_SQL,
  type ConsentInput,
  type HistoryReport,
  type IngestionRunInput,
  type PushLogInput,
  type SaveReportBundleInput,
} from './repo-types.js';

export interface Repo {
  insertMember(input: Omit<Member, 'id'>): Member;
  getMember(id: number): Member | undefined;
  upsertEvent(event: Event): Event;
  saveReportBundle(bundle: SaveReportBundleInput): { reportId: number };
  acceptAttribution(reportId: number, all: boolean): number;
  findSummaryRows(reportDate: string): SummaryRow[];
  findHistory(
    actorMemberId: number,
    memberId: number,
    from: string,
    to: string,
  ): HistoryReport[];
  insertIngestionRun(input: IngestionRunInput): number;
  insertPushLog(input: PushLogInput): number;
  insertConsent(input: ConsentInput): number;
}

function iso(clock: Clock, at: Date): string {
  return toZonedIsoString(clock, at);
}

export function createRepo(db: Database.Database, clock: Clock): Repo {
  const selectMember = db.prepare(`SELECT * FROM member WHERE id = ?`);
  const selectEventByDedupe = db.prepare(`SELECT * FROM event WHERE dedupe_key = ?`);

  const insertMemberStmt = db.prepare(`
    INSERT INTO member (github_login, feishu_open_id, display_name, email, manager_id, active, created_at)
    VALUES (@githubLogin, @feishuOpenId, @displayName, @email, @managerId, @active, @createdAt)
  `);

  const insertEventStmt = db.prepare(`
    INSERT INTO event (
      member_id, source, source_id, kind, occurred_at, title, detail, dedupe_key, is_primary, run_id, payload, created_at
    ) VALUES (
      @memberId, @source, @sourceId, @kind, @occurredAt, @title, @detail, @dedupeKey, @isPrimary, @runId, @payload, @createdAt
    )
  `);

  function insertMember(input: Omit<Member, 'id'>): Member {
    const result = insertMemberStmt.run({
      githubLogin: input.githubLogin,
      feishuOpenId: input.feishuOpenId ?? null,
      displayName: input.displayName,
      email: input.email ?? null,
      managerId: input.managerId ?? null,
      active: input.active ? 1 : 0,
      createdAt: iso(clock, clock.now()),
    });
    const id = Number(result.lastInsertRowid);
    const row = selectMember.get(id) as MemberRow | undefined;
    if (row === undefined) {
      throw new SdrError(ERROR_CODES.STORE_TRANSACTION_FAILED, '成员写入后读取失败');
    }
    return mapMemberFull(row);
  }

  function getMember(id: number): Member | undefined {
    const row = selectMember.get(id) as MemberRow | undefined;
    return row === undefined ? undefined : mapMemberFull(row);
  }

  function upsertEvent(event: Event): Event {
    try {
      const result = insertEventStmt.run({
        memberId: event.memberId,
        source: event.source,
        sourceId: event.sourceId,
        kind: event.kind,
        occurredAt: iso(clock, event.occurredAt),
        title: event.title,
        detail: event.detail ?? null,
        dedupeKey: event.dedupeKey,
        isPrimary: event.isPrimary ? 1 : 0,
        runId: event.runId,
        payload: event.payload === undefined ? null : JSON.stringify(event.payload),
        createdAt: iso(clock, clock.now()),
      });
      const id = Number(result.lastInsertRowid);
      const row = db.prepare(`SELECT * FROM event WHERE id = ?`).get(id) as EventRow;
      return mapEvent(row);
    } catch (error) {
      if (!isUniqueViolation(error)) throw error;
      const existing = selectEventByDedupe.get(event.dedupeKey) as EventRow | undefined;
      if (existing === undefined) {
        throw new SdrError(ERROR_CODES.STORE_TRANSACTION_FAILED, '去重键冲突但未找到既有事件', {
          cause: error,
        });
      }
      return mapEvent(existing);
    }
  }

  const insertReport = db.prepare(`
    INSERT INTO report (member_id, report_date, status, body, generated_at, pushed_at)
    VALUES (@memberId, @reportDate, @status, @body, @generatedAt, @pushedAt)
  `);

  const insertEntry = db.prepare(`
    INSERT INTO entry (
      report_id, time_block, state, content, order_index, original_date, source_event_id,
      is_manual, attribution_kind, attribution_confirmed
    ) VALUES (
      @reportId, @timeBlock, @state, @content, @orderIndex, @originalDate, @sourceEventId,
      @isManual, @attributionKind, @attributionConfirmed
    )
  `);

  const insertEntryMember = db.prepare(`
    INSERT INTO entry_member (entry_id, member_id, role) VALUES (@entryId, @memberId, @role)
  `);

  const insertSourceLink = db.prepare(`
    INSERT INTO source_link (entry_id, link_type, target) VALUES (@entryId, @linkType, @target)
  `);

  function saveReportBundle(bundle: SaveReportBundleInput): { reportId: number } {
    const write = db.transaction(() => {
      const reportResult = insertReport.run({
        memberId: bundle.report.memberId,
        reportDate: bundle.report.reportDate,
        status: bundle.report.status,
        body: bundle.report.body ?? null,
        generatedAt: iso(clock, bundle.report.generatedAt),
        pushedAt:
          bundle.report.pushedAt === undefined ? null : iso(clock, bundle.report.pushedAt),
      });
      const reportId = Number(reportResult.lastInsertRowid);

      for (const item of bundle.entries) {
        const entryResult = insertEntry.run({
          reportId,
          timeBlock: item.timeBlock,
          state: item.state,
          content: item.content,
          orderIndex: item.orderIndex,
          originalDate: item.originalDate ?? null,
          sourceEventId: item.sourceEventId ?? null,
          isManual: item.isManual ? 1 : 0,
          attributionKind: item.attributionKind,
          attributionConfirmed: item.attributionConfirmed ? 1 : 0,
        });
        const entryId = Number(entryResult.lastInsertRowid);

        for (const em of item.members) {
