        }
        for (const link of item.links) {
          insertSourceLink.run({ entryId, linkType: link.linkType, target: link.target });
        }
      }

      return { reportId };
    });

    try {
      return write();
    } catch (error) {
      throw new SdrError(ERROR_CODES.STORE_TRANSACTION_FAILED, '日报四表写入失败', { cause: error });
    }
  }

  function acceptAttribution(reportId: number, all: boolean): number {
    const sql = all
      ? `UPDATE entry SET attribution_confirmed = 1 WHERE report_id = ? AND attribution_confirmed = 0`
      : `UPDATE entry SET attribution_confirmed = 1
         WHERE report_id = ? AND attribution_confirmed = 0 AND attribution_kind = 'fallback'`;
    const result = db.prepare(sql).run(reportId);
    return result.changes;
  }

  function findSummaryRows(reportDate: string): SummaryRow[] {
    const rows = db.prepare(SUMMARY_ROWS_SQL).all(reportDate) as SummaryQueryRow[];
    type MutableSummary = {
      memberId: number;
      displayName: string;
      status: ReportStatus | null;
      entryCount: number;
      byState: Record<EntryState, number>;
    };
    const grouped = new Map<number, MutableSummary>();

    for (const row of rows) {
      let summary = grouped.get(row.member_id);
      if (summary === undefined) {
        summary = {
          memberId: row.member_id,
          displayName: row.display_name,
          status: row.status,
          entryCount: 0,
          byState: emptyByState(),
        };
        grouped.set(row.member_id, summary);
      }
      if (row.state !== null) {
        const count = row.state_count;
        summary.byState[row.state] += count;
        summary.entryCount += count;
      }
    }

    return [...grouped.values()];
  }

  function assertHistoryAccess(actorMemberId: number, targetMemberId: number): void {
    if (actorMemberId === targetMemberId) return;
    const target = getMember(targetMemberId);
    if (target?.managerId === actorMemberId) return;
    throw new HistoryAccessDenied();
  }

  function findHistory(
    actorMemberId: number,
    memberId: number,
    from: string,
    to: string,
  ): HistoryReport[] {
    assertHistoryAccess(actorMemberId, memberId);

    const reports = db
      .prepare(
        `SELECT * FROM report WHERE member_id = ? AND report_date >= ? AND report_date <= ? ORDER BY report_date`,
      )
      .all(memberId, from, to);

    return reports.map((row) => {
      const report = mapReportRow(row as import('./repo-types.js').ReportRow);
      const entryRows = db
        .prepare(`SELECT * FROM entry WHERE report_id = ? ORDER BY order_index`)
        .all(report.id) as import('./repo-types.js').EntryRow[];
      return { report, entries: entryRows.map(mapEntryRow) };
    });
  }

  function insertIngestionRun(input: IngestionRunInput): number {
    const result = db
      .prepare(
        `INSERT INTO ingestion_run (run_id, source, started_at, finished_at, result, error_code, error_msg, event_count)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        input.runId,
        input.source,
        iso(clock, input.startedAt),
        input.finishedAt === undefined ? null : iso(clock, input.finishedAt),
        input.result,
        input.errorCode ?? null,
        input.errorMsg ?? null,
        input.eventCount,
      );
    return Number(result.lastInsertRowid);
  }

  function insertPushLog(input: PushLogInput): number {
    const result = db
      .prepare(
        `INSERT INTO push_log (report_date, channel, sent_at, result, retry_count)
         VALUES (?, ?, ?, ?, ?)`,
      )
      .run(
        input.reportDate,
        input.channel,
        iso(clock, input.sentAt),
        input.result,
        input.retryCount ?? 0,
      );
    return Number(result.lastInsertRowid);
  }

  function insertConsent(input: ConsentInput): number {
    const result = db
      .prepare(`INSERT INTO consent (member_id, agreed_at, scope) VALUES (?, ?, ?)`)
      .run(input.memberId, iso(clock, input.agreedAt), input.scope);
    return Number(result.lastInsertRowid);
  }

  return {
    insertMember,
    getMember,
    upsertEvent,
    saveReportBundle,
    acceptAttribution,
    findSummaryRows,
    findHistory,
    insertIngestionRun,
    insertPushLog,
    insertConsent,
  };
}

